static irqreturn_t bcm2835_dma_callback ( int irq , void * data ) { struct bcm2835_chan * c = data ; struct bcm2835_desc * d ; unsigned long flags ; if ( c -> irq_flags & IRQF_SHARED ) { flags = readl ( c -> chan_base + BCM2835_DMA_CS ) ; if ( ! ( flags & BCM2835_DMA_INT ) ) { return IRQ_NONE ; } } spin_lock_irqsave ( & c -> vc . lock , flags ) ; writel ( BCM2835_DMA_INT | BCM2835_DMA_ACTIVE , c -> chan_base + BCM2835_DMA_CS ) ; d = c -> desc ; if ( d ) { if ( d -> cyclic ) { vchan_cyclic_callback ( & d -> vd ) ; } if ( ! readl ( c -> chan_base + BCM2835_DMA_ADDR ) ) { vchan_cookie_complete ( & c -> desc -> vd ) ; } } spin_unlock_irqrestore ( & c -> vc . lock , flags ) ; return IRQ_HANDLED ; } 